const page = (folder, name, n, { partial, parent = id(301), order, title = name, copy, summary }) => {
  const base = `web-pages/${folder}/${name}.webpage`;
  const content = `web-pages/${folder}/content-pages/${name}.en-US.webpage`;
  const record = (extra) =>
    YAML.stringify({
      adx_name: title,
      adx_title: title,
      adx_partialurl: partial,
      adx_parentpageid: parent,
      adx_pagetemplateid: PAGE_TEMPLATE,
      adx_publishingstateid: PUBLISHED,
      adx_hiddenfromsitemap: false,
      adx_displayorder: order,
      ...extra,
    });
  return {
    [`${base}.yml`]: record({ adx_webpageid: id(n), adx_isroot: true }),
    [`${base}.copy.html`]: copy,
    [`${base}.summary.html`]: summary,
    [`${content}.yml`]: record({
      adx_webpageid: id(n + 50),
      adx_isroot: false,
      adx_rootwebpageid: id(n),
      adx_webpagelanguageid: LANGUAGE,
    }),
    [`${content}.copy.html`]: copy,
    [`${content}.summary.html`]: summary,
  };
};

