/** Writes the example export and the fixture's files into `dir` (the portal export root). */
export function writeDynamicPortal(dir) {
  fs.cpSync(path.join(EXAMPLE_PROJECT, 'portal'), dir, { recursive: true });
  for (const [rel, content] of Object.entries(DYNAMIC_FILES)) {
    fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
    fs.writeFileSync(path.join(dir, rel), content);
  }
  return dir;
}

/**
 * The Mirage renderer of a portal export with the example project's Solution metadata and records, wired as
 * mirage/server.mjs wires it (renderComponent, renderCodeComponent), without a listener.
 */
export async function exportRenderer(portalDir) {
  const config = YAML.parse(fs.readFileSync(path.join(EXAMPLE_PROJECT, 'paqvilo.config.yml'), 'utf8'));
  const portal = applyObserved(await importPortal(portalDir), config.sites.example.mirage.observed);
  const roots = ['code-solution', 'metadata', 'solution'].map((root) => path.join(EXAMPLE_PROJECT, root));
  const scan = await scanSolutionSources(roots, { order: 'explicit' });
  const schema = buildSolutionSchema(scan, { lcid: 1033 });
  const codeComponents = await importCodeComponents(scan.layers, { retainBytes: true });
  const metadata = await importSolutionMetadata(roots, { portal, scan, schema });
  const data = await importSolutionData(roots, { scan, schema, lcid: 1033 });
  const fixtures = JSON.parse(fs.readFileSync(path.join(EXAMPLE_PROJECT, 'pack/fixtures.json'), 'utf8'));
  const store = await new DataStore({
    state: {
      mappings: data.mappings,
      relationships: data.relationships,
      tables: Object.fromEntries(Object.entries(fixtures).filter(([table]) => data.mappings[table])),
      settings: { permissionMode: 'permissive' },
    },
  }).init();
  const webFormSessions = createWebFormSessions();
  const pcf = (spec) =>
    renderCodeComponent({ portal, catalog: codeComponents, metadata, identity: {}, mappings: data.mappings, ...spec });
  const renderer = createPortalRenderer(portal, {
    metadata,
    codeCatalogue: codeComponents,
    // Liquid fetchxml reads the same invented records (mirage/server.mjs wires its read provider the same way).
    fetchXml: (xml, user, _request, fetchOptions) => store.fetchXml(xml, user ?? { id: null, roles: [] }, fetchOptions),
    renderComponent: async (kind, args, context) => {
      const components = [],
        explicit = [];
      const provenance = (result) =>
        componentRenderResult(result, {
          components,
          explicit,
          index: renderer.sourceIndex(context?.__language?.id),
          tag: kind,
          args,
        });
      if (kind === 'codecomponent')
        return provenance(pcf({ name: args?.name ?? args?.id, args, onRendered: (item) => explicit.push(item) }));
      const rendered = await renderComponent(
        kind,
        typeof args === 'string' ? args : (args?.name ?? args?.id ?? args?.key ?? ''),
        context,
        {
          portal,
          store,
          readProvider: store,
          args: typeof args === 'string' ? { name: args } : (args ?? {}),
          metadata,
          codeComponent: pcf,
          config: {},
          schemas: metadata.componentSchemas,
          renderLiquid: (source, ctx) => renderer.renderString(source, ctx),
          webFormSessions,
          webFormOwner: () => 'visitor:fixture',
          onProgressRendered: (item) => explicit.push(item),
          onComponentRendered: (item) => components.push(item),
        },
      );
      return provenance(rendered);
    },
  });
  return { portal, renderer };
}
